values ('200ea630-644d-4ae8-9e16-d2d008ff4d59', 'ca30fa78-411b-434c-acfa-0996a9a70fcf', '{"retreat_id": "0f61bab5-bdea-46e7-8953-2dfa3db35cc6", "heading": "Dates & Rates", "manual_dates_text": "Oct 31 - Nov 7, 2026", "manual_tiers": [{"name": "Dorm", "price": "$895"}, {"name": "Triple", "price": "$1,095"}, {"name": "Double", "price": "$1,395"}, {"name": "Single", "price": "$1,995"}], "manual_cta_label": "Book Now", "manual_cta_href": "https://anamaya.secure.retreat.guru/program/somatic-retreat-costa-rica-colynn-cespedes/?form=1&lang=en"}'::jsonb)
