insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('200ea630-644d-4ae8-9e16-d2d008ff4d59', 'c229572b-1c0d-446e-8c7c-f05b2852bb92', '{"html": "<p>You\u2019ve been holding it together for so long. The exhaustion in your body isn\u2019t weakness. It\u2019s a message you haven\u2019t had space to hear.</p><p>Regulate is a body-based retreat rooted in somatic experiencing, nervous system science, and yoga as a real-life practice.</p><p>Not a bootcamp. Not a detox. A gentle, trauma-informed space where slowness is medicine and your body\u2019s signals are finally worth listening to.</p><p>You\u2019ll leave with a deeper understanding of your own nervous system, practical tools for regulation in real life, and a body that remembers what safety feels like.</p><p>No prior experience required. Just a willingness to come home to yourself.</p>", "padding_y_px": 48}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('200ea630-644d-4ae8-9e16-d2d008ff4d59', '403e929f-18cd-4fde-a6e1-685237575195', '{"heading": "Optional Workshops", "intro": "", "tiers": [{"name": "PACKAGE PRICE: For all 4 workshops", "price": "$150"}], "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('200ea630-644d-4ae8-9e16-d2d008ff4d59', 'aa9b32a9-9236-45b4-b6ea-4b386021a0d4', '{"html": "<h3>Relating: Building Relationship with Self, Body, and Nervous System</h3><p><em>90-minute workshop</em></p><p>Before we can regulate, we have to relate. This opening workshop explores how the stories we carry live in the body as physical sensation and emotion. You&#8217;ll develop the language of interoception, learning to notice what is happening before trying to change it. A powerful foundation for everything that follows. This Workshop is 90 minutes. Price is $40.</p><h3>Releasing: Moving Emotion Through the Body</h3><p><em>90-minute workshop</em></p><p>This experiential workshop is a dynamic somatic meditation, adapted through a trauma-informed, choice-based lens. Using movement, breath, sound, and stillness, we create space for the safe discharge of stored stress and emotional energy. This isn&#8217;t about forcing catharsis. It&#8217;s about learning to trust your body&#8217;s capacity to complete what was once interrupted. This Workshop is 90 minutes. Price is $40.</p><h3>Regulation: Boundaries, Capacity, and Emotional Intelligence</h3><p><em>90-minute workshop</em></p><p>Awareness without application only takes us so far. In this coaching-focused workshop, we bring somatic concepts into everyday life, exploring boundaries not as walls or rules, but as nervous system skills. You&#8217;ll learn to recognise your body&#8217;s signals of yes, no, and enough, and begin building a more regulated relationship with your energy and time. This Workshop is 90 minutes. Price is $40.</p><h3>Reverence: Integration, Ceremony, and Celebration</h3><p><em>120-minute workshop</em></p><p>We close with a cacao ceremony and integration space, a time to honour the work you&#8217;ve done, the body that carried you here, and the community you&#8217;ve built. This final workshop is less about learning and more about landing. Softening, opening, and marking the journey with presence, pleasure, and connection. This Workshop is 2 hours. Price is $50.</p><h3>PACKAGE PRICE: For all 4 workshops</h3><p><em>$150</em></p>", "padding_y_px": 24}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('200ea630-644d-4ae8-9e16-d2d008ff4d59', 'd384555b-4b04-4acc-8826-de4825a1ec0e', '{"images": [{"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/ee6afaac-3f31-42b9-a5d4-feea52aa96e4/gallery/hero-image-82-5d39039d.png", "alt": "Regulate: A Somatic Experiencing Retreat \u2013 Colynn Cespedes"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/ee6afaac-3f31-42b9-a5d4-feea52aa96e4/gallery/lower-deck-yoga-class-cropped-300x300-51700eee.png", "alt": "Regulate: A Somatic Experiencing Retreat \u2013 Colynn Cespedes"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/relax-on-the-pool-deck-at-anamaya-resort-300x300-87bae3ad.jpg", "alt": "Regulate: A Somatic Experiencing Retreat \u2013 Colynn Cespedes"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/spa-1-300x300-c701562a.jpg", "alt": "Regulate: A Somatic Experiencing Retreat \u2013 Colynn Cespedes"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/cristiane-link-300x300-c44147a2.jpg", "alt": "Regulate: A Somatic Experiencing Retreat \u2013 Colynn Cespedes"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/food-5-300x300-342b7e50.jpg", "alt": "Regulate: A Somatic Experiencing Retreat \u2013 Colynn Cespedes"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/53c43106-46e6-4cb6-ae76-6a59601dd3b4/gallery/colynn-vosburgh-781x800-0dbf91b8.jpg", "alt": "Regulate: A Somatic Experiencing Retreat \u2013 Colynn Cespedes"}], "layout": "grid", "columns": 3, "lightbox": true, "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('200ea630-644d-4ae8-9e16-d2d008ff4d59', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Colynn Cespedes", "bio_html": "<p>Colynn Cespedes\u2019 journey from Western medicine to holistic healing is one of resilience, transformation, and deep devotion. Beginning in healthcare in 2000, she worked her way from Home Support Worker to Emergency Room Nurse before pursuing medical school\u2014believing it was her true calling. But alongside her studies, yoga pulled her in a different direction. The contrast was undeniable. Eventually, she made the courageous choice to leave medicine behind and dedicate herself fully to yoga, coaching, and energy work.</p><p>With thousands of hours of training and over a hundred Yoga Teacher Trainings led, Colynn integrates her deep clinical knowledge with ancient yogic wisdom. Her teaching blends anatomy, energy work, and past life regressions with humor, real-life wisdom, and spiritual depth. She believes yoga is a sacred roadmap\u2014postures reconnect us with the body, breath bridges the mind and soul, and slowing down isn\u2019t just something we do\u2014it\u2019s a way of being.</p><p>At <strong>Anamaya</strong>, Colynn\u2019s dynamic morning classes awaken the body and mind, while candlelit Yin and Restorative practices in the evening offer deep release. More than just movement, her classes and workshops guide students to shift their perspective, disentangle from life\u2019s dramas, and embrace true presence.</p><p>Now living a nomadic life, with Costa Rica as her home base, Colynn finds joy in the ocean, jungle, and the people she meets. Whether through yoga, coaching, or healing work, her mission is to help others reconnect\u2014with themselves, their bodies, and the infinite possibilities life has to offer.</p>", "photo_url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/200ea630-644d-4ae8-9e16-d2d008ff4d59/gallery/colynn-vosburgh-781x800-0dbf91b8.jpg"}'::jsonb)
on conflict do nothing;
