values ('d94f2f3e-b65a-4f8e-9fb4-bf7ef0ab4fc5', 'ca30fa78-411b-434c-acfa-0996a9a70fcf', '{"retreat_id": "495ea078-5a61-4ddf-806b-6bb6936202d3", "heading": "Dates & Rates", "manual_dates_text": "Aug 8 - 15, 2026", "manual_tiers": [{"name": "Dorm", "price": "$895"}, {"name": "Triple", "price": "$1,095"}, {"name": "Double", "price": "$1,395"}, {"name": "Single", "price": "$1,995"}], "manual_cta_label": "Book Now", "manual_cta_href": "https://anamaya.com/rg-calendar/"}'::jsonb)
