insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('d94f2f3e-b65a-4f8e-9fb4-bf7ef0ab4fc5', 'c229572b-1c0d-446e-8c7c-f05b2852bb92', '{"html": "<p><strong>The Art of Thriving: Energy, Healing & Creation</strong></p><p>&nbsp;</p><h3>Are you ready to do more than just survive?<br>This retreat is your invitation to step out of burnout and into a life where you thrive.</h3><p>&nbsp;</p><h3>Join Leslie Lutsch and Colleen Navas at Anamaya Resort in Costa Rica for a transformational week designed to awaken your energy, heal your spirit, and unlock your creativity.</h3><p>&nbsp;</p><h3>Through chakra-based movement, restorative yoga nidra, sound healing, and hands-on creativity workshops, you\u2019ll release what\u2019s been holding you back and plant the seeds for the future you desire.</h3><p>&nbsp;</p><h3>All of this unfolds in Anamaya\u2019s stunning jungle-ocean setting, with nourishing food, meaningful connections, and space to finally put yourself first.</h3><p>&nbsp;</p><h3><strong>Don\u2019t wait for \u201csomeday.\u201d The time to thrive is now.</strong></h3><p><strong>Reserve your spot today!</strong></p>", "padding_y_px": 48}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('d94f2f3e-b65a-4f8e-9fb4-bf7ef0ab4fc5', '403e929f-18cd-4fde-a6e1-685237575195', '{"heading": "Optional Workshops", "intro": "", "tiers": [{"name": "THRIVE Workshop", "price": "$35\u2013$60", "note": "90-minute workshop"}, {"name": "Tapping Into Creativity For Emotional Healing", "price": "$60", "note": "90-minute workshop"}], "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('d94f2f3e-b65a-4f8e-9fb4-bf7ef0ab4fc5', 'aa9b32a9-9236-45b4-b6ea-4b386021a0d4', '{"html": "<h3>THRIVE Workshop</h3><p><em>90-minute workshop &mdash; $35\u2013$60</em></p><p><b>Transform your Daily Toolbox: Free your Spirit and unleash your creative side in order to THRIVE.</b></p><p>Within this series there will be 2 different sessions scheduled throughout the week. We will travel through the depths of our bodies &#8211; physical, mental, emotional, spiritual, we will touch it all. Overall, we will dive deeper and deeper into our energetic body and see what seeds of intention we can plant into our futures.</p><p>We will move through each chakra, what it looks like, and we will learn to build practices to strengthen and heal our chakras. These grounding and eye-opening workshops introduce the chakra system in a way that feels real, accessible, and deeply supportive.</p><p>Helping you understand how stress, and daily life can impact your energy and sense of self.Through a blend of gentle, intuitive movement, guided meditation, and reflective journaling, you\u2019ll begin to reconnect with your body, rebuild your foundation, and reignite your inner strength.These deeply restorative workshops are designed to help you move from awareness into true energetic healing and alignment.</p><p>You\u2019ll leave with simple, powerful tools you can return to in everyday life&#8230; so you can feel more open, more aligned, and more like yourself again.</p><h3>Tapping Into Creativity For Emotional Healing</h3><p><em>90-minute workshop &mdash; $60</em></p><p>Discover how creative expression can be a powerful tool for emotional healing and personal transformation. In this intimate and inspiring workshop, Colleen Navas shares her personal journey of using jewelry making as a lifeline during a challenging chapter of her life, and invites you to explore your own healing through creativity.</p><p>Through guided journaling and vision boarding, you&#8217;ll tap into your inner wisdom, uncover emotional insights, and begin crafting a visual and written map of your transformation. No artistic experience needed, just a willingness to explore, express, and heal.</p><p><strong>What to Expect:</strong></p><ul><li>A heartfelt story of healing through creativity</li><li>Reflective journaling prompts to unlock emotional clarity</li><li>A hands-on vision boarding session to visualize your path forward</li><li>A safe, supportive space for sharing and connection</li></ul>", "padding_y_px": 24}'::jsonb)
on conflict do nothing;
