values ('d94f2f3e-b65a-4f8e-9fb4-bf7ef0ab4fc5', 'd384555b-4b04-4acc-8826-de4825a1ec0e', '{"images": [{"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/relax-on-the-pool-deck-at-anamaya-resort-300x300-87bae3ad.jpg", "alt": "The Art of Thriving \u2013 Leslie Lutsch & Colleen Navas"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/yoga-bonus-300x300-e2ddbe11.jpg", "alt": "The Art of Thriving \u2013 Leslie Lutsch & Colleen Navas"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/spa-1-300x300-c701562a.jpg", "alt": "The Art of Thriving \u2013 Leslie Lutsch & Colleen Navas"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/cristiane-link-300x300-c44147a2.jpg", "alt": "The Art of Thriving \u2013 Leslie Lutsch & Colleen Navas"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/food-5-300x300-342b7e50.jpg", "alt": "The Art of Thriving \u2013 Leslie Lutsch & Colleen Navas"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/leslie-819x800-e5b2e47a.jpg", "alt": "The Art of Thriving \u2013 Leslie Lutsch & Colleen Navas"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/colleen-navas-2ed8b2bf.png", "alt": "The Art of Thriving \u2013 Leslie Lutsch & Colleen Navas"}], "layout": "grid", "columns": 3, "lightbox": true, "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('d94f2f3e-b65a-4f8e-9fb4-bf7ef0ab4fc5', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Leslie Lutsch", "bio_html": "<p>Leslie Lutsch lives in the heart of the Rocky Mountains in Colorado, where her days are shaped by skiing, rafting, climbing, and a deep love for nature. But her greatest passion\u2014and the thread that runs through every part of her life\u2014is yoga.</p><p>Leslie first came to Anamaya over a decade ago as a student, and that journey changed everything. What began as a retreat blossomed into years of dedicated study across Costa Rica, Indonesia, and India, leading her through 200, 300, and 500-hour trainings. She went on to assist her beloved teacher for three years of Yoga Teacher Trainings at Anamaya and eventually to teach her own retreats.</p><p>With more than 10 years of teaching experience\u2014from owning her own studio, to workshops, to even horse yoga\u2014Leslie has seen yoga\u2019s ability to transform lives in countless ways. Her classes weave together movement, philosophy, and spiritual depth, always returning to one truth: the balance of discipline and surrender.</p><p>She believes yoga is not just a practice but a way of living\u2014a daily act of choosing awareness, compassion, and alignment with your dharma. Her philosophy is grounded in the wisdom of the Bhagavad Gita and the belief that through action, discipline, and presence, we can move toward our highest selves.</p><p>Leslie lives by the motto, <em>\u201cLive for the moments that take your breath away.\u201d</em> Her teaching invites you to do the same\u2014to step fully into the present moment, awaken your energy, and discover the magic that unfolds when body, mind, and spirit align.</p>", "photo_url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/leslie-819x800-e5b2e47a.jpg", "ao_person_id": "4c5b6bc5-bacf-439b-9a74-a647dd591e07"}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('d94f2f3e-b65a-4f8e-9fb4-bf7ef0ab4fc5', '4a08c4ca-1b80-4e05-871e-97f7dafe90f3', '{"responsive_mode": "fixed", "role": "Co-Teacher", "name": "Colleen Navas", "bio_html": "<p>Colleen Navas is a devoted mom of two young boys who recently traded the beaches of San Diego for the mountains of Colorado. While she carries the ocean in her heart, she\u2019s embraced the mountain lifestyle and the vibrant creative energy of her new home.</p><p>A yogi for more than a decade, Colleen\u2019s path was first inspired by her sister Leslie, whose encouragement led her deeper into her practice. Yoga remains a grounding force in her life, helping her return to balance through all of life\u2019s seasons. She\u2019s honored to join Leslie again in Costa Rica, guiding others through this transformational retreat.</p><p>Colleen\u2019s love for creativity blossomed during a difficult chapter in her life, when jewelry making became more than a hobby\u2014it became meditation, healing, and a way to transform pain into beauty. Today, she shares this passion to help others tap into their own creativity, resilience, and emotional renewal.</p><p>Her workshops are about more than artistic expression\u2014they\u2019re an invitation to slow down, connect with your inner wisdom, and discover how creativity can be a powerful tool for healing and transformation.</p>", "photo_url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/colleen-navas-2ed8b2bf.png", "ao_person_id": "826bfee1-f3f7-443e-af29-f5368e22a7b7"}'::jsonb)
on conflict do nothing;
