values ('d0022fca-e2ae-4c01-9f11-76f36b0e122b', 'c229572b-1c0d-446e-8c7c-f05b2852bb92', '{"html": "<p>If you\u2019ve been craving a transformational experience that reconnects you to your power, your body, and your spirit, the <em>Anatomy of Sacred Breath Retreat</em> at Anamaya is exactly what you\u2019ve been waiting for.</p><p>Led by one of our most beloved teachers, Cristiane Machado, this retreat is a powerful invitation to come home to yourself.</p><p>With Cristiane\u2019s intuitive guidance and deeply healing workshops \u2013 you\u2019ll move through emotional blocks and step into clarity, confidence, and joy.</p><p>Whether it\u2019s your first time at Anamaya or your first retreat ever, this week will nourish your soul and help you break through what\u2019s been holding you back.</p>", "padding_y_px": 48}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('d0022fca-e2ae-4c01-9f11-76f36b0e122b', '403e929f-18cd-4fde-a6e1-685237575195', '{"heading": "Optional Workshops", "intro": "", "tiers": [{"name": "The Essence of Sacred Breath Workshop", "price": "$135", "note": "120-minute workshop"}, {"name": "Cacao Ceremony", "price": "$50", "note": "60-minute workshop"}, {"name": "Z-Fit Movement Workshop", "price": "$15", "note": "60-minute workshop"}], "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('d0022fca-e2ae-4c01-9f11-76f36b0e122b', 'aa9b32a9-9236-45b4-b6ea-4b386021a0d4', '{"html": "<h3>The Essence of Sacred Breath Workshop</h3><p><em>120-minute workshop &mdash; $135</em></p><p>Your breath is more than a life force \u2013 it is a gateway to presence, peace, and transformation. In this workshop, you\u2019ll learn to cultivate mindfulness through each inhale and exhale, embracing the sacred rhythm that connects you to yourself and the world around you.</p><p>Through <em>The Anatomy of Sacred Breath</em>, you\u2019ll uncover practices that calm the mind, nurture inner tranquility, and awaken a deeper sense of authenticity. As you surrender to the flow of breath, you may feel lifted, renewed, and more aligned with your true self.</p><h3>Cacao Ceremony</h3><p><em>60-minute workshop &mdash; $50</em></p><p>Cacao has long been cherished as the \u201cFood of the Gods,\u201d a sacred plant medicine used for centuries to open the heart, awaken joy, and restore balance. Rich in antioxidants, minerals, and the bliss-boosting compound anandamide, cacao is both nourishing for the body and expansive for the spirit.</p><p>In this ceremony, guided by Cristiane Machado, you\u2019ll be welcomed with a ritual cleansing before receiving cacao prepared and blessed in the Mayan tradition. Once the cacao is shared, Cristiane will lead you through a meditation that helps align mind, voice, and heart, creating space for deep connection and self-discovery.</p><p>Every experience is unique \u2013 some feel waves of emotion and release, others a sense of joy, liberation, or heightened clarity. Many describe it as a journey inward, one that leaves them lighter, more open, and deeply connected to themselves.</p><p>This is more than just drinking chocolate \u2013 it\u2019s an invitation to explore the magic of cacao as a doorway to healing, connection, and bliss.</p><h3>Z-Fit Movement Workshop</h3><p><em>60-minute workshop &mdash; $15</em></p><p>Get ready to move, laugh, and let go in this one-of-a-kind class designed to unlock the hips and free the body through self-expression.</p><p>With energizing international music and simple, inviting moves, Z-Fit is for everyone \u2013 even if you\u2019ve never considered yourself a dancer. It\u2019s less about performance and more about joy, connection, and feeling good in your own skin.</p><p>This isn\u2019t your typical workout. It\u2019s a celebration of movement that feels playful, easy, and deeply freeing. Come exactly as you are, meet yourself on the dance floor, and discover how good it feels to love the body you\u2019re in.</p>", "padding_y_px": 24}'::jsonb)
on conflict do nothing;
