values ('d0022fca-e2ae-4c01-9f11-76f36b0e122b', 'd384555b-4b04-4acc-8826-de4825a1ec0e', '{"images": [{"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/d6e8e73e-71a9-4e07-89c1-802d892b4954/gallery/hero-image-53-4cffdffa.png", "alt": "The Anatomy of Sacred Breath \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/d6e8e73e-71a9-4e07-89c1-802d892b4954/gallery/retreat-on-pool-edge-1200px-300x300-a16df9ae.jpg", "alt": "The Anatomy of Sacred Breath \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/d6e8e73e-71a9-4e07-89c1-802d892b4954/gallery/yoga_mg_2881-800x600-1-300x300-31d7e222.jpg", "alt": "The Anatomy of Sacred Breath \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/spa-1-300x300-c701562a.jpg", "alt": "The Anatomy of Sacred Breath \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/b625eaa2-a2e9-456e-81dd-1a69d4c6a623/gallery/img_5352-300x300-f024c432.jpg", "alt": "The Anatomy of Sacred Breath \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/d6e8e73e-71a9-4e07-89c1-802d892b4954/gallery/psx_20200926_135655-300x300-3a0c7299.jpg", "alt": "The Anatomy of Sacred Breath \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/d6e8e73e-71a9-4e07-89c1-802d892b4954/gallery/cristiane-machado-headshot-anamaya-6a949530.png", "alt": "The Anatomy of Sacred Breath \u2013 Cristiane Machado"}], "layout": "grid", "columns": 3, "lightbox": true, "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('d0022fca-e2ae-4c01-9f11-76f36b0e122b', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Cristiane Machado", "bio_html": "<p>Cristiane Machado, a Brazilian-born citizen of the Universe, is a passionate advocate for reconnecting with our divine essence and collective consciousness through therapeutic tools. After moving to the USA in 1999 and attending the Florida School of Massage, Cristiane embarked on a transformative journey that deepened her connection to energy work, yoga, and meditation\u2014practices that reignited her spiritual awakening.</p><p>A dreamer at heart, Cristiane envisions a world of equality and community, where everyone is valued beyond societal labels. As a bodyworker, 200-hour yoga guide specializing in Hatha Yoga, and facilitator of well-being, she creates safe spaces for growth and transformation. Cristiane\u2019s journey led her to Montezuma, Costa Rica, where she continues to guide others in reawakening their divinity through yoga retreats, sacred cacao circles, and her YogaLoka Project.</p><p>Cristiane\u2019s teaching philosophy centers on Yoga as a lifelong practice, a path to self-knowledge, acceptance, and inner peace. She believes in the power of connecting breath, physical effort, and observation to achieve well-being and heal old patterns. Her inclusive teaching style blends Hatha, Yin, and laughing yoga, making the practice accessible to all. Cristiane\u2019s greatest joy is helping her students take their yoga practice off the mat and into the world, fostering kindness and connection.</p>", "photo_url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/d0022fca-e2ae-4c01-9f11-76f36b0e122b/gallery/cristiane-machado-headshot-anamaya-6a949530.png", "ao_person_id": "ee6e48a8-2116-45ea-9b6c-a7f344e10bd7"}'::jsonb)
on conflict do nothing;
