values ('d6e8e73e-71a9-4e07-89c1-802d892b4954', '403e929f-18cd-4fde-a6e1-685237575195', '{"heading": "Optional Workshops", "intro": "", "tiers": [{"name": "The Essence of Sacred Breath Workshop", "price": "$135", "note": "120-minute workshop"}, {"name": "Cacao Ceremony", "price": "$50", "note": "60-minute workshop"}, {"name": "Z-Fit Movement Workshop", "price": "$15", "note": "60-minute workshop"}], "padding_y_px": 32}'::jsonb)
