insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('d6e8e73e-71a9-4e07-89c1-802d892b4954', 'aa9b32a9-9236-45b4-b6ea-4b386021a0d4', '{"html": "<h3>The Essence of Sacred Breath Workshop</h3><p><em>120-minute workshop &mdash; $135</em></p><p>Your breath is more than a life force \u2013 it is a gateway to presence, peace, and transformation. In this workshop, you\u2019ll learn to cultivate mindfulness through each inhale and exhale, embracing the sacred rhythm that connects you to yourself and the world around you.</p><p>Through <em>The Anatomy of Sacred Breath</em>, you\u2019ll uncover practices that calm the mind, nurture inner tranquility, and awaken a deeper sense of authenticity. As you surrender to the flow of breath, you may feel lifted, renewed, and more aligned with your true self.</p><h3>Cacao Ceremony</h3><p><em>60-minute workshop &mdash; $50</em></p><p>Cacao has long been cherished as the \u201cFood of the Gods,\u201d a sacred plant medicine used for centuries to open the heart, awaken joy, and restore balance. Rich in antioxidants, minerals, and the bliss-boosting compound anandamide, cacao is both nourishing for the body and expansive for the spirit.</p><p>In this ceremony, guided by Cristiane Machado, you\u2019ll be welcomed with a ritual cleansing before receiving cacao prepared and blessed in the Mayan tradition. Once the cacao is shared, Cristiane will lead you through a meditation that helps align mind, voice, and heart, creating space for deep connection and self-discovery.</p><p>Every experience is unique \u2013 some feel waves of emotion and release, others a sense of joy, liberation, or heightened clarity. Many describe it as a journey inward, one that leaves them lighter, more open, and deeply connected to themselves.</p><p>This is more than just drinking chocolate \u2013 it\u2019s an invitation to explore the magic of cacao as a doorway to healing, connection, and bliss.</p><h3>Z-Fit Movement Workshop</h3><p><em>60-minute workshop &mdash; $15</em></p><p>Get ready to move, laugh, and let go in this one-of-a-kind class designed to unlock the hips and free the body through self-expression.</p><p>With energizing international music and simple, inviting moves, Z-Fit is for everyone \u2013 even if you\u2019ve never considered yourself a dancer. It\u2019s less about performance and more about joy, connection, and feeling good in your own skin.</p><p>This isn\u2019t your typical workout. It\u2019s a celebration of movement that feels playful, easy, and deeply freeing. Come exactly as you are, meet yourself on the dance floor, and discover how good it feels to love the body you\u2019re in.</p>", "padding_y_px": 24}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('d6e8e73e-71a9-4e07-89c1-802d892b4954', 'd384555b-4b04-4acc-8826-de4825a1ec0e', '{"images": [{"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/d6e8e73e-71a9-4e07-89c1-802d892b4954/gallery/hero-image-53-4cffdffa.png", "alt": "The Anatomy of Sacred Breath \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/d6e8e73e-71a9-4e07-89c1-802d892b4954/gallery/retreat-on-pool-edge-1200px-300x300-a16df9ae.jpg", "alt": "The Anatomy of Sacred Breath \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/d6e8e73e-71a9-4e07-89c1-802d892b4954/gallery/yoga_mg_2881-800x600-1-300x300-31d7e222.jpg", "alt": "The Anatomy of Sacred Breath \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/spa-1-300x300-c701562a.jpg", "alt": "The Anatomy of Sacred Breath \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/b625eaa2-a2e9-456e-81dd-1a69d4c6a623/gallery/img_5352-300x300-f024c432.jpg", "alt": "The Anatomy of Sacred Breath \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/d6e8e73e-71a9-4e07-89c1-802d892b4954/gallery/psx_20200926_135655-300x300-3a0c7299.jpg", "alt": "The Anatomy of Sacred Breath \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/d6e8e73e-71a9-4e07-89c1-802d892b4954/gallery/cristiane-machado-headshot-anamaya-6a949530.png", "alt": "The Anatomy of Sacred Breath \u2013 Cristiane Machado"}], "layout": "grid", "columns": 3, "lightbox": true, "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('d6e8e73e-71a9-4e07-89c1-802d892b4954', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Cristiane Machado", "bio_html": "<p>Cristiane Machado, a Brazilian-born citizen of the Universe, is a passionate advocate for reconnecting with our divine essence and collective consciousness through therapeutic tools. After moving to the USA in 1999 and attending the Florida School of Massage, Cristiane embarked on a transformative journey that deepened her connection to energy work, yoga, and meditation\u2014practices that reignited her spiritual awakening.</p><p>A dreamer at heart, Cristiane envisions a world of equality and community, where everyone is valued beyond societal labels. As a bodyworker, 200-hour yoga guide specializing in Hatha Yoga, and facilitator of well-being, she creates safe spaces for growth and transformation. Cristiane\u2019s journey led her to Montezuma, Costa Rica, where she continues to guide others in reawakening their divinity through yoga retreats, sacred cacao circles, and her YogaLoka Project.</p><p>Cristiane\u2019s teaching philosophy centers on Yoga as a lifelong practice, a path to self-knowledge, acceptance, and inner peace. She believes in the power of connecting breath, physical effort, and observation to achieve well-being and heal old patterns. Her inclusive teaching style blends Hatha, Yin, and laughing yoga, making the practice accessible to all. Cristiane\u2019s greatest joy is helping her students take their yoga practice off the mat and into the world, fostering kindness and connection.</p>", "photo_url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/d0022fca-e2ae-4c01-9f11-76f36b0e122b/gallery/cristiane-machado-headshot-anamaya-6a949530.png", "ao_person_id": "ee6e48a8-2116-45ea-9b6c-a7f344e10bd7"}'::jsonb)
on conflict do nothing;
