values ('a19ea53e-8606-4dfd-a9f2-8cce7c4c3b34', 'ca30fa78-411b-434c-acfa-0996a9a70fcf', '{"retreat_id": "2553f262-0112-4591-aace-a080083bd3d7", "heading": "Dates & Rates", "manual_dates_text": "June 27 - July 4, 2026", "manual_tiers": [{"name": "Dorm", "price": "$895"}, {"name": "Triple", "price": "$1,095"}, {"name": "Double", "price": "$1,395"}, {"name": "Single", "price": "$1,995"}], "manual_cta_label": "Book Now", "manual_cta_href": "https://anamaya.com/rg-calendar/"}'::jsonb)
