insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('a19ea53e-8606-4dfd-a9f2-8cce7c4c3b34', 'c229572b-1c0d-446e-8c7c-f05b2852bb92', '{"html": "<p>You have been taking care of everything and everyone. What about you?</p><h3>Missy and David hold space for every part of you that has been waiting for attention. Your body, your relationships, your sense of self, and the patterns quietly running your life.</h3><p>Their yoga, sound healing, partner practices, and workshops are invitations, not obligations.</p><p>Come solo or bring someone you love. Leave knowing yourself more deeply.</p><p><b>Design Your Perfect Week: </b>Your retreat, your way. Join yoga classes, book spa treatments, explore adventures&#8230; or do nothing but rest by the pool. Everything is optional and paid at checkout, so you can decide what feels right each day.</p><p>Discover renewal and transformation at Anamaya in Montezuma, Costa Rica.</p>", "padding_y_px": 48}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('a19ea53e-8606-4dfd-a9f2-8cce7c4c3b34', '403e929f-18cd-4fde-a6e1-685237575195', '{"heading": "Optional Workshops", "intro": "", "tiers": [{"name": "Connection & Mutual Awakening", "price": "$25", "note": "90-minute workshop"}, {"name": "Awaken Your Path, Sound Bath", "price": "$40", "note": "75-minute workshop"}], "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('a19ea53e-8606-4dfd-a9f2-8cce7c4c3b34', 'aa9b32a9-9236-45b4-b6ea-4b386021a0d4', '{"html": "<h3>Connection & Mutual Awakening</h3><p><em>90-minute workshop &mdash; $25</em></p><p><strong>Partner Yoga + Trust & Communication</strong></p><p>A gentle partner yoga session for couples or solo participants (we\u2019ll pair you if you come alone). In our tech-filled world of smartphones and screens, learning to truly connect with others matters more than ever. Partner yoga strengthens relationships, marriages, and friendships while teaching skills to form deeper bonds even with strangers. Through supported poses, gentle assists, synchronized breathing, and trust-building movements, you\u2019ll find balance, let go of control, and deepen presence together.</p><h3>Awaken Your Path, Sound Bath</h3><p><em>75-minute workshop &mdash; $40</em></p><p><strong>Deep Relaxation & Vibrational Healing</strong></p><p>A deeply immersive sound bath using crystal bowls, chimes, voice, and nature sounds to release tension, calm the nervous system, clear inner blocks, and bring fresh clarity to your awakened journey.</p><h3>Roam Free: Travel the World, Do What You Love</h3><p><strong>Pursue Your Passion & Be Financially Free</strong></p><p>Imagine travelling the globe on your terms, pursuing your passions, waking up in new places and working (or not working) exactly how you want \u2013 while money flows with ease instead of stress. This empowering workshop shows you how to achieve true financial independence for a location-independent life. Blending practical steps like building remote income streams, smart tax strategies, mindful money habits, and yogic principles of ease and surrender, you\u2019ll gain actionable tools, mindset shifts, and inspiration to make world-roaming freedom your reality. No more waiting for \u201csomeday.\u201d Start designing your nomadic passion-fueled life today.</p>", "padding_y_px": 24}'::jsonb)
on conflict do nothing;
