values ('a19ea53e-8606-4dfd-a9f2-8cce7c4c3b34', 'd384555b-4b04-4acc-8826-de4825a1ec0e', '{"images": [{"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/a19ea53e-8606-4dfd-a9f2-8cce7c4c3b34/gallery/hero-image-65-cd65e9db.png", "alt": "Awaken Your Path \u2013 Missy & David Hartley"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/relax-on-the-pool-deck-at-anamaya-resort-300x300-87bae3ad.jpg", "alt": "Awaken Your Path \u2013 Missy & David Hartley"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/yoga-bonus-300x300-e2ddbe11.jpg", "alt": "Awaken Your Path \u2013 Missy & David Hartley"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/a19ea53e-8606-4dfd-a9f2-8cce7c4c3b34/gallery/infrared-sauna-at-anamaya-resort-300x300-4b2c7354.png", "alt": "Awaken Your Path \u2013 Missy & David Hartley"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/cristiane-link-300x300-c44147a2.jpg", "alt": "Awaken Your Path \u2013 Missy & David Hartley"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/food-5-300x300-342b7e50.jpg", "alt": "Awaken Your Path \u2013 Missy & David Hartley"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/a19ea53e-8606-4dfd-a9f2-8cce7c4c3b34/gallery/missy-hartley-headshot-6f60b371.png", "alt": "Awaken Your Path \u2013 Missy & David Hartley"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/a19ea53e-8606-4dfd-a9f2-8cce7c4c3b34/gallery/david-hartley-headshot-e601bded.png", "alt": "Awaken Your Path \u2013 Missy & David Hartley"}], "layout": "grid", "columns": 3, "lightbox": true, "padding_y_px": 32}'::jsonb)
