insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('a19ea53e-8606-4dfd-a9f2-8cce7c4c3b34', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Missy Hartley", "bio_html": "<p>Missy&#8217;s yoga journey began in 2016, a pivotal year that would change her life. It wasn\u2019t until she met her husband David that the magic of yoga truly clicked for her. He introduced her to the mesmerizing Anamaya Resort, nestled in the lush jungles of Costa Rica. As the sun set on her last day there, a fire ignited within her\u2014she knew this was where she belonged. Determined to teach in that paradise, Missy and David immersed themselves in an intensive yoga teacher training at Anamaya, diving deeper into their shared passion for wellness.</p><p>Today, Missy&#8217;s life is a beautiful blend of travel, yoga, and adventure. She\u2019s the proud fur mom of two playful cats and finds joy in hiking the rugged, picturesque mountains of Arizona. But she\u2019s not just a yogi\u2014Missy is also a Financial Assistant at Wealth Wellness, the dynamic firm she co-runs with David. She combines her deep understanding of wellness with financial savvy, guiding clients toward not just wealth, but holistic prosperity.</p><p>In her yoga practice, Missy\u2019s mission is clear: to make yoga accessible to everyone. She shatters the myth that flexibility is a must, creating a welcoming space for students of all shapes, sizes, and abilities. Her classes are more than just a series of poses\u2014they\u2019re an empowering journey, especially for women seeking confidence and strength. Through her own story of self-discovery, Missy inspires her students to embrace their uniqueness, proving that yoga is as much about uplifting the soul as it is about strengthening the body. Whether on the mat or in life, she\u2019s all about finding balance, joy, and transformation.</p>", "photo_url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/a19ea53e-8606-4dfd-a9f2-8cce7c4c3b34/gallery/missy-hartley-headshot-6f60b371.png"}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('a19ea53e-8606-4dfd-a9f2-8cce7c4c3b34', '4a08c4ca-1b80-4e05-871e-97f7dafe90f3', '{"responsive_mode": "fixed", "role": "Co-Teacher", "name": "David Hartley", "bio_html": "<p>David Hartley is a seasoned financial advisor with over two decades of experience, proudly rooted in Michigan and a graduate of Michigan State University. After eight enriching years in Colorado, he now calls Arizona home. Beyond his professional expertise, David has a profound passion for yoga, which he integrates into his financial practice, creating a unique approach that fosters holistic well-being and mindful financial planning.</p><p>David\u2019s journey into yoga began with his first teacher training at Lifetime Fitness, where he developed a strong foundation in the practice. Shortly after his training he went to Anamaya and experienced his full potential, and started manifesting the life he wanted. Returning to Anamaya for a second time was a profoundly meaningful experience for David. This time, he was accompanied by his new wife, Missy, celebrating their honeymoon at the very place where he had experienced such personal transformation. Their shared love for yoga and the serenity of Anamaya marked the beginning of a new chapter in their lives together. The transformative experience not only enriched his personal growth but also inspired him to intertwine the grounding principles of yoga with his financial practice.</p><p>David\u2019s philosophy in both yoga and financial advising is rooted in the belief that true wealth goes beyond monetary success; it encompasses a balanced and fulfilled life. By integrating mindfulness and yoga principles into his financial practice, he empowers his clients to achieve clarity and purpose, aligning their financial goals with their personal values and well-being. David is honored to teach at Anamaya and to bring his teachings to the same place that gave him so much wisdom.</p>", "photo_url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/a19ea53e-8606-4dfd-a9f2-8cce7c4c3b34/gallery/david-hartley-headshot-e601bded.png"}'::jsonb)
on conflict do nothing;
update public.url_inventory set cms_template_id = '2c89c7ed-da33-44b7-9455-1a97bf75b512' where id = 'a19ea53e-8606-4dfd-a9f2-8cce7c4c3b34';
